function GUICommonAdActivityPanelWindow:onShow()
    self.isShow = true
    self:updateList()

    self:onTick()
    LuaTimer:cancel(self.countdownTimer)
    self.countdownTimer = LuaTimer:scheduleTimer(function()
        self:onTick()
    end, 1000, -1)
    self:addTimer(self.countdownTimer)
end

function GUICommonAdActivityPanelWindow:onHide()
    LuaTimer:cancel(self.countdownTimer)
    self.isShow = false
end

